CREATE TABLE `user` (
 id BIGINT NOT NULL AUTO_INCREMENT, phone VARCHAR(256) NULL, phone_hash VARCHAR(64) NULL, phone_last4 VARCHAR(4) NULL,
 nickname VARCHAR(64) NULL, avatar VARCHAR(512) NULL, status VARCHAR(20) NOT NULL DEFAULT 'active',
 create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, update_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
 is_deleted TINYINT(1) NOT NULL DEFAULT 0, PRIMARY KEY(id), UNIQUE KEY uk_user_phone_hash(phone_hash), KEY idx_user_phone_last4(phone_last4), KEY idx_user_status(status)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE user_address (
 id BIGINT NOT NULL AUTO_INCREMENT, user_id BIGINT NOT NULL, receiver VARCHAR(64) NOT NULL, phone VARCHAR(256) NOT NULL, phone_last4 VARCHAR(4) NOT NULL,
 province VARCHAR(64), city VARCHAR(64), district VARCHAR(64), detail VARCHAR(255) NOT NULL, is_default TINYINT(1) NOT NULL DEFAULT 0,
 create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, update_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
 is_deleted TINYINT(1) NOT NULL DEFAULT 0, PRIMARY KEY(id), KEY idx_address_user(user_id,is_deleted)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE category (
 id BIGINT NOT NULL AUTO_INCREMENT, parent_id BIGINT NOT NULL DEFAULT 0, name VARCHAR(64) NOT NULL, sort INT NOT NULL DEFAULT 0, status VARCHAR(20) NOT NULL DEFAULT 'active',
 create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, update_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, is_deleted TINYINT(1) NOT NULL DEFAULT 0,
 PRIMARY KEY(id), KEY idx_category_parent(parent_id,status)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE brand (
 id BIGINT NOT NULL AUTO_INCREMENT, name VARCHAR(100) NOT NULL, logo VARCHAR(512), description VARCHAR(500), status VARCHAR(20) NOT NULL DEFAULT 'active',
 create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, update_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, is_deleted TINYINT(1) NOT NULL DEFAULT 0,
 PRIMARY KEY(id), UNIQUE KEY uk_brand_name(name)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE product (
 id BIGINT NOT NULL AUTO_INCREMENT, category_id BIGINT NOT NULL, brand_id BIGINT NULL, name VARCHAR(200) NOT NULL, subtitle VARCHAR(500), cover_url VARCHAR(512),
 price DECIMAL(10,2) NOT NULL, original_price DECIMAL(10,2), status VARCHAR(20) NOT NULL DEFAULT 'draft', sales BIGINT NOT NULL DEFAULT 0,
 create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, update_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, is_deleted TINYINT(1) NOT NULL DEFAULT 0,
 PRIMARY KEY(id), KEY idx_product_category(category_id,status), KEY idx_product_brand(brand_id), KEY idx_product_name(name)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE inventory (
 id BIGINT NOT NULL AUTO_INCREMENT, product_id BIGINT NOT NULL, store_id BIGINT NULL, quantity INT NOT NULL DEFAULT 0, locked_quantity INT NOT NULL DEFAULT 0, version INT NOT NULL DEFAULT 0,
 create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, update_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, is_deleted TINYINT(1) NOT NULL DEFAULT 0,
 PRIMARY KEY(id), UNIQUE KEY uk_inventory_product_store(product_id,store_id), KEY idx_inventory_store(store_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE inventory_log (
 id BIGINT NOT NULL AUTO_INCREMENT, product_id BIGINT NOT NULL, store_id BIGINT NULL, change_quantity INT NOT NULL, change_type VARCHAR(30) NOT NULL, reference_no VARCHAR(64), remark VARCHAR(255),
 create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, update_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, is_deleted TINYINT(1) NOT NULL DEFAULT 0,
 PRIMARY KEY(id), KEY idx_inventory_log_product(product_id,create_time)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE cart_item (
 id BIGINT NOT NULL AUTO_INCREMENT, user_id BIGINT NOT NULL, product_id BIGINT NOT NULL, quantity INT NOT NULL, selected TINYINT(1) NOT NULL DEFAULT 1,
 create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, update_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, is_deleted TINYINT(1) NOT NULL DEFAULT 0,
 PRIMARY KEY(id), UNIQUE KEY uk_cart_user_product(user_id,product_id), KEY idx_cart_user(user_id,is_deleted)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE `order` (
 id BIGINT NOT NULL AUTO_INCREMENT, order_no VARCHAR(40) NOT NULL, user_id BIGINT NOT NULL, status VARCHAR(30) NOT NULL DEFAULT 'pending_payment', total_amount DECIMAL(10,2) NOT NULL,
 pay_amount DECIMAL(10,2) NOT NULL, address_snapshot JSON, remark VARCHAR(500), expire_time DATETIME NULL,
 create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, update_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, is_deleted TINYINT(1) NOT NULL DEFAULT 0,
 PRIMARY KEY(id), UNIQUE KEY uk_order_no(order_no), KEY idx_order_user_status(user_id,status,create_time)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE order_item (
 id BIGINT NOT NULL AUTO_INCREMENT, order_id BIGINT NOT NULL, product_id BIGINT NOT NULL, product_name VARCHAR(200) NOT NULL, product_image VARCHAR(512), quantity INT NOT NULL, unit_price DECIMAL(10,2) NOT NULL, amount DECIMAL(10,2) NOT NULL,
 create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, update_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, is_deleted TINYINT(1) NOT NULL DEFAULT 0,
 PRIMARY KEY(id), KEY idx_order_item_order(order_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE payment (
 id BIGINT NOT NULL AUTO_INCREMENT, payment_no VARCHAR(40) NOT NULL, order_id BIGINT NOT NULL, user_id BIGINT NOT NULL, amount DECIMAL(10,2) NOT NULL, channel VARCHAR(30), status VARCHAR(20) NOT NULL DEFAULT 'pending', paid_time DATETIME NULL,
 create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, update_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, is_deleted TINYINT(1) NOT NULL DEFAULT 0,
 PRIMARY KEY(id), UNIQUE KEY uk_payment_no(payment_no), KEY idx_payment_order(order_id,status)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE aftersale (
 id BIGINT NOT NULL AUTO_INCREMENT, aftersale_no VARCHAR(40) NOT NULL, order_id BIGINT NOT NULL, user_id BIGINT NOT NULL, reason VARCHAR(500), amount DECIMAL(10,2) NOT NULL, status VARCHAR(30) NOT NULL DEFAULT 'pending',
 create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, update_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, is_deleted TINYINT(1) NOT NULL DEFAULT 0,
 PRIMARY KEY(id), UNIQUE KEY uk_aftersale_no(aftersale_no), KEY idx_aftersale_user(user_id,status)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE work_order (
 id BIGINT NOT NULL AUTO_INCREMENT, work_order_no VARCHAR(40) NOT NULL, user_id BIGINT NOT NULL, store_id BIGINT NULL, type VARCHAR(30) NOT NULL, status VARCHAR(30) NOT NULL DEFAULT 'pending', title VARCHAR(200) NOT NULL, description TEXT,
 create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, update_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, is_deleted TINYINT(1) NOT NULL DEFAULT 0,
 PRIMARY KEY(id), UNIQUE KEY uk_work_order_no(work_order_no), KEY idx_work_order_status(status,store_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE work_order_log (
 id BIGINT NOT NULL AUTO_INCREMENT, work_order_id BIGINT NOT NULL, operator_id BIGINT, action VARCHAR(50) NOT NULL, content VARCHAR(1000),
 create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, update_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, is_deleted TINYINT(1) NOT NULL DEFAULT 0,
 PRIMARY KEY(id), KEY idx_work_order_log(work_order_id,create_time)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE department (
 id BIGINT NOT NULL AUTO_INCREMENT, parent_id BIGINT NOT NULL DEFAULT 0, name VARCHAR(100) NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'active', create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, update_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, is_deleted TINYINT(1) NOT NULL DEFAULT 0,
 PRIMARY KEY(id), KEY idx_department_parent(parent_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE position (
 id BIGINT NOT NULL AUTO_INCREMENT, name VARCHAR(100) NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'active', create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, update_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, is_deleted TINYINT(1) NOT NULL DEFAULT 0,
 PRIMARY KEY(id), UNIQUE KEY uk_position_name(name)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE employee (
 id BIGINT NOT NULL AUTO_INCREMENT, department_id BIGINT NULL, position_id BIGINT NULL, username VARCHAR(64) NOT NULL, password_hash VARCHAR(100) NOT NULL, phone VARCHAR(256), phone_last4 VARCHAR(4), status VARCHAR(20) NOT NULL DEFAULT 'active',
 create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, update_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, is_deleted TINYINT(1) NOT NULL DEFAULT 0,
 PRIMARY KEY(id), UNIQUE KEY uk_employee_username(username), KEY idx_employee_phone(phone_last4)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE role (
 id BIGINT NOT NULL AUTO_INCREMENT, name VARCHAR(100) NOT NULL, role_key VARCHAR(64) NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'active', create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, update_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, is_deleted TINYINT(1) NOT NULL DEFAULT 0,
 PRIMARY KEY(id), UNIQUE KEY uk_role_key(role_key)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE permission (
 id BIGINT NOT NULL AUTO_INCREMENT, name VARCHAR(100) NOT NULL, permission_key VARCHAR(128) NOT NULL, create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, update_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, is_deleted TINYINT(1) NOT NULL DEFAULT 0,
 PRIMARY KEY(id), UNIQUE KEY uk_permission_key(permission_key)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE role_permission (
 id BIGINT NOT NULL AUTO_INCREMENT, role_id BIGINT NOT NULL, permission_id BIGINT NOT NULL, create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, update_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, is_deleted TINYINT(1) NOT NULL DEFAULT 0,
 PRIMARY KEY(id), UNIQUE KEY uk_role_permission(role_id,permission_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE store (
 id BIGINT NOT NULL AUTO_INCREMENT, name VARCHAR(100) NOT NULL, phone VARCHAR(256), phone_last4 VARCHAR(4), province VARCHAR(64), city VARCHAR(64), district VARCHAR(64), address VARCHAR(255), status VARCHAR(20) NOT NULL DEFAULT 'active',
 create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, update_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, is_deleted TINYINT(1) NOT NULL DEFAULT 0,
 PRIMARY KEY(id), KEY idx_store_status(status), KEY idx_store_phone(phone_last4)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE coupon (
 id BIGINT NOT NULL AUTO_INCREMENT, name VARCHAR(100) NOT NULL, amount DECIMAL(10,2) NOT NULL, minimum_amount DECIMAL(10,2) NOT NULL DEFAULT 0, start_time DATETIME NOT NULL, end_time DATETIME NOT NULL, quantity INT NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'active',
 create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, update_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, is_deleted TINYINT(1) NOT NULL DEFAULT 0,
 PRIMARY KEY(id), KEY idx_coupon_status_time(status,start_time,end_time)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE user_coupon (
 id BIGINT NOT NULL AUTO_INCREMENT, user_id BIGINT NOT NULL, coupon_id BIGINT NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'unused', used_order_id BIGINT NULL, expire_time DATETIME NULL,
 create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, update_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, is_deleted TINYINT(1) NOT NULL DEFAULT 0,
 PRIMARY KEY(id), KEY idx_user_coupon(user_id,status,expire_time)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE operation_log (
 id BIGINT NOT NULL AUTO_INCREMENT, operator_id BIGINT NULL, operation VARCHAR(200) NOT NULL, request_uri VARCHAR(500), request_method VARCHAR(10), trace_id VARCHAR(64), duration_ms BIGINT, success TINYINT(1) NOT NULL DEFAULT 1,
 create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, update_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, is_deleted TINYINT(1) NOT NULL DEFAULT 0,
 PRIMARY KEY(id), KEY idx_operation_operator(operator_id,create_time), KEY idx_operation_trace(trace_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE search_hotword (
 id BIGINT NOT NULL AUTO_INCREMENT, word VARCHAR(100) NOT NULL, search_count BIGINT NOT NULL DEFAULT 0, status VARCHAR(20) NOT NULL DEFAULT 'active', create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, update_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, is_deleted TINYINT(1) NOT NULL DEFAULT 0,
 PRIMARY KEY(id), UNIQUE KEY uk_hotword(word), KEY idx_hotword_count(search_count)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE system_config (
 id BIGINT NOT NULL AUTO_INCREMENT, config_key VARCHAR(100) NOT NULL, config_value TEXT NULL, description VARCHAR(255), create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, update_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, is_deleted TINYINT(1) NOT NULL DEFAULT 0,
 PRIMARY KEY(id), UNIQUE KEY uk_system_config_key(config_key)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
